  "version": "1.5.8",
  "description": "Chrome extension that creates a pre-filled Google Calendar event from the event details on the current web page.",
  "private": true,
  "scripts": {
    "test": "node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON --test \"extension-test/**/*.test.js\" \"dev/build/test/**/*.test.js\" \".claudinite/local/packs/gcec/tasks/*/test/**/*.test.js\" \".claudinite/local/packs/**/*.test.mjs\" \"dev/requirements/extractor/**/*.test.js\" \"dev/build/release/**/*.test.js\" \"dev/requirements/shared/**/*.test.js\" \"dev/requirements/behavior/**/*.test.js\" \"dev/requirements/logic/**/*.test.js\" \"dev/requirements/requirements-coverage.test.js\"",
    "test:offline": "node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON --test extension-test/event-extractors/extraction.test.js extension-test/event-extractors/helpers/derive-timezone.test.js extension-test/events-popup/derive-wait-selector.test.js extension-test/events-popup/build-calendar-url.test.js extension-test/events-popup/source-request-view.test.js dev/build/release/shipping-files.test.js dev/build/test/load-order-generated.test.js extension-test/integration/load-order.test.js extension-test/events-popup/popup.test.js extension-test/host-policy.test.js extension-test/events-popup/events-view.test.js extension-test/integration/registry-idempotent.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/triage.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/attach-sample-url.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/extractor-naming.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/extractor-scaffold.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/case-quality.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/prepare.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/task.test.js .claudinite/local/packs/gcec/tasks/create-extractor/test/scraperapi.test.js extension-test/integration/supported-domains.test.js extension-test/icon/toolbar-icon.test.js extension-test/integration/extension-loads.test.js dev/requirements/logic/product-requirements.test.js",
    "test:live": "node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON --test dev/requirements/extractor/live.test.js dev/requirements/extractor/extractor-support.test.js dev/requirements/extractor/generic-coverage/generic-coverage.test.js",
    "test:ui": "node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON --test dev/requirements/shared/render/visual-snapshots.test.js",
    "test:e2e": "node --test \"dev/requirements/heavy/**/*.test.js\"",
    "build": "node dev/build/release/build-zip.js",
    "index": "node dev/build/gen-load-order.js",
    "refresh:ui": "node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON dev/requirements/shared/render/refresh-snapshots.js",
    "regen": "node dev/build/gen-load-order.js && node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON dev/requirements/shared/render/refresh-snapshots.js && node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON --test dev/requirements/extractor/generic-coverage/generic-coverage.test.js"
  },
  "license": "MIT",
  "_scriptNotes": {
    "--disable-warning=MODULE_TYPELESS_PACKAGE_JSON": "Deliberate, reviewed suppression (issue #305). The popup's ES-module graph (extension/config.js, extension/host-policy.js, extension/events-popup/build-calendar-url.js, extension/events-popup/popup.js, extension/events-popup/*.js) is loaded as .js with no package.json \"type\" (the rest of the repo is CommonJS), so Node parses-as-CJS-then-reparses-as-ESM and warns on every test run. This is a Node-loader-only artifact: the shipped extension loads these via <script type=\"module\"> in extension/events-popup/popup.html and Chrome never reads package.json, so nothing is wrong in production. Suppressing only this one code keeps other warnings visible (the canon warning-suppression discipline). Applied only to the node invocations that import the ESM graph."
  },
  "devDependencies": {
    "@resvg/resvg-js": "^2.6.2",
    "jsdom": "^29.1.1",
    "pixelmatch": "^7.2.0",
    "pngjs": "^7.0.0",
    "satori": "^0.26.0"
  },
  "_dependencyNotes": {
    "jsdom": "Test-only. Provides a DOM implementation (extension-test/harness.js) so the unmodified extractor scripts (extension/event-extractors/) can be run and asserted against in Node, exactly as they execute in a browser. Not shipped with the extension.",
    "satori": "Test-only. Renders the popup's HTML/CSS-subset tree to SVG for UI snapshot tests (dev/requirements/shared/render/popup-renderer.js), since it isn't a real screenshot of the popup.",
    "@resvg/resvg-js": "Test-only. Rasterizes the SVG produced by satori into a PNG for UI snapshot tests (dev/requirements/shared/render/popup-renderer.js).",
    "pngjs": "Test-only. Decodes/encodes the PNG snapshots compared in the UI tests (dev/requirements/shared/render/visual-snapshots.test.js).",
    "pixelmatch": "Test-only. Performs pixel-level diffing between rendered and reference PNGs in the UI tests (dev/requirements/shared/render/visual-snapshots.test.js)."
  }
}
